const b = $input.first().json.body || {};
const token = String(b.token || '');
const action = String(b.action || '');
if (!/^[a-f0-9]{64}$/.test(token)) return [{ json: { ok: false, error: 'session_invalide' } }];
if (['list', 'moderate', 'report_done'].indexOf(action) === -1) return [{ json: { ok: false, error: 'requete_invalide' } }];
const AUTH = "a.id=1 AND a.session_hash=SHA2('" + token + "',256) AND a.session_expires > NOW()";
let q0 = 'SELECT 1';
if (action === 'moderate') {
  const cid = parseInt(b.cid, 10);
  const st = b.decision === 'approve' ? 'demande' : b.decision === 'reject' ? 'rejetee' : null;
  if (!Number.isInteger(cid) || cid < 1 || !st) return [{ json: { ok: false, error: 'requete_invalide' } }];
  q0 = "UPDATE conversations c JOIN admin_access a ON " + AUTH + " SET c.status='" + st + "' WHERE c.id=" + cid + " AND c.status='moderation'";
}
if (action === 'report_done') {
  const cid = parseInt(b.cid, 10);
  if (!Number.isInteger(cid) || cid < 1) return [{ json: { ok: false, error: 'requete_invalide' } }];
  q0 = "UPDATE member_reports r JOIN admin_access a ON " + AUTH + " SET r.status='traite' WHERE r.conversation_id=" + cid + " AND r.status='nouveau'";
}
const q1 = "SELECT a.id AS admin_id, c.id AS cid, c.status, c.created_at AS cdate, ma.id AS a_id, ma.email AS a_email, ma.display_name AS a_nom, ma.gender AS a_genre, mb.id AS b_id, mb.email AS b_email, mb.display_name AS b_nom, mb.gender AS b_genre, (SELECT JSON_ARRAYAGG(JSON_OBJECT('id', r.id, 'par', r.reporter_id, 'motif', r.reason, 'details', r.details, 'date', DATE_FORMAT(r.created_at,'%Y-%m-%dT%H:%i'), 'statut', r.status)) FROM member_reports r WHERE r.conversation_id=c.id) AS rapports, m.id AS mid, m.sender_id, m.body, m.created_at AS mdate " +
  "FROM (SELECT 1 AS x) d LEFT JOIN admin_access a ON " + AUTH + " LEFT JOIN conversations c ON a.id IS NOT NULL LEFT JOIN members ma ON ma.id=c.member_a LEFT JOIN members mb ON mb.id=c.member_b LEFT JOIN messages m ON m.conversation_id=c.id " +
  "ORDER BY (c.status='moderation') DESC, (SELECT COUNT(*) FROM member_reports r2 WHERE r2.conversation_id=c.id AND r2.status='nouveau') DESC, c.id DESC, m.id ASC LIMIT 1000";
return [{ json: { ok: true, q0, q1 } }];

const rows = $input.all().map(i => i.json);
if (!rows.length || rows[0].admin_id === null || rows[0].admin_id === undefined) return [{ json: { success: false, error: 'session_invalide' } }];
const map = new Map();
for (const r of rows) {
  if (r.cid === null || r.cid === undefined) continue;
  if (!map.has(r.cid)) map.set(r.cid, {
    cid: r.cid, statut: r.status, date: r.cdate,
    a: { id: r.a_id, email: r.a_email, nom: r.a_nom, genre: r.a_genre },
    b: { id: r.b_id, email: r.b_email, nom: r.b_nom, genre: r.b_genre }, messages: [],
    signalements: (function (x) { try { const v = typeof x === 'string' ? JSON.parse(x) : x; return Array.isArray(v) ? v : []; } catch (e) { return []; } })(r.rapports)
  });
  if (r.mid !== null && r.mid !== undefined) map.get(r.cid).messages.push({ id: r.mid, de_a: Number(r.sender_id) === Number(r.a_id), texte: r.body, date: r.mdate });
}
const conversations = Array.from(map.values());
return [{ json: { success: true, a_traiter: conversations.filter(c => c.signalements.some(s => s.statut === 'nouveau')).length, a_moderer: conversations.filter(c => c.statut === 'moderation').length, conversations } }];
